import { ref } from 'vue';

const AbortControllerDemo = {
  setup() {
    const data = ref(null);
    const loading = ref(false);
    const error = ref(null);

    const fetchData = () => {
      const controller = new AbortController();
      loading.value = true;
      error.value = null;

      fetch('https://jsonplaceholder.typicode.com/posts/1', {
        signal: controller.signal
      })
        .then(response => response.json())
        .then(json => {
          data.value = json;
          loading.value = false;
        })
        .catch(err => {
          if (err.name !== 'AbortError') {
            error.value = err.message;
            loading.value = false;
          }
        });

      // Return cleanup function here
      return () => controller.abort();
    };

    return {
      data,
      loading,
      error,
      fetchData
    };
  },
  template: `
    <div>
      <h1>AbortController Demo</h1>
      <div v-if="loading">Loading...</div>
      <div v-else-if="error">Error: {{ error }}</div>
      <div v-else-if="data">
        <h2>{{ data.title }}</h2>
        <p>{{ data.body }}</p>
      </div>
      <div v-else>No data loaded yet.</div>

